                    this.isOpening = false;
                    this.rootScope.$broadcast('unauthenticated');
                });
            }
        }
        if (this.socketCloseTimer) {
            clearTimeout(this.socketCloseTimer);
            this.socketCloseTimer = null;
        }
    }
  }

