{
    load: (url: string): Promise<void> => new Promise<void>((resolve, reject) => {
      const isCss = /\.css($|\?)/i.test(url);
      const el: any = document.createElement(isCss ? 'link' : 'script');
      if (isCss) {
        el.rel = 'stylesheet';
        el.href = url;
      } else {
        el.src = url;
        el.async = false;
      }
      el.onload = () => resolve();
      el.onerror = () => reject();
      document.head.appendChild(el);
    })
  }

